In the context of a graph represented as an adjacency list, where weights are the edge costs between nodes, let's write the function `shortest_path` to find the shortest path from a source node to a target node using Dijkstra's algorithm. Here's a complete implementation:

```python
import heapq

def shortest_path(graph, source, target):
    # Priority queue to track nodes to visit, ordered by distance from source
    priority_queue = [(0, source)]
    # Dictionary to track the shortest distance to each node
    distances = {node: float('inf') for node in graph}
    # Dictionary to track the shortest path to each node
    paths = {node: None for node in graph}
    distances[source] = 0

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_node == target:
            # Reconstruct the path from target to source using the paths dictionary
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = paths[current_node]
            return (current_distance, path[::-1])

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                paths[neighbor] = current_node
                heapq.heappush(priority_queue, (distance, neighbor))

    # If we reach here, the target is unreachable
    return (float('inf'), None)

