def shortest_path(graph, source, target):
    from queue import PriorityQueue
    import math

    def relax(node, neighbour, weight):
        nonlocal graph
        if weight + graph[node][neighbour] < graph[neighbour].get(node, math.inf):
            graph[neighbour][node] = weight + graph[node][neighbour]
            return True
        return False

    def dijkstra(graph, source):
        distances = {node: math.inf for node in graph}
        distances[source] = 0
        visited = set()
        pq = PriorityQueue()
        pq.put((0, source))

        while not pq.empty():
            current_distance, current_node = pq.get()
            if current_node not in visited:
                visited.add(current_node)
                for neighbour, weight in graph[current_node].items():
                    if relax(current_node, neighbour, weight):
                        pq.put((current_distance + weight, neighbour))
        return distances

    distances = dijkstra(graph, source)
    if distances[target] == math.inf:
        return (math.inf, None)
    else:
        path = [target]
        while path[-1] != source:
            for node, weight in graph[path[-1]].items():
                if weight + graph[path[-1]][node] == distances[path[-1]]:
                    path.append(node)
                    break
        path.reverse()
        return (distances[target], path)

