def shortest_path(graph, source, target):
    from collections import deque
    
    # Initialize the distance dictionary and the previous node dictionary
    # Distance dictionary records the shortest distance from the source to each node.
    # Previous node dictionary records the previous node in the shortest path to the current node.
    dist = {node: float("inf") for node in graph}
    prev = {node: None for node in graph}
    dist[source] = 0
    
    # Initialize the priority queue (min-heap) with the source node, where the distance is 0
    q = deque([(source, 0)])
    
    while q:
        current_node, current_distance = q.popleft()
        
        # If we reached the target node, return the shortest path and its distance
        if current_node == target:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = prev[current_node]
            path.reverse()
            return (current_distance, path)
        
        # Go through all neighbors of the current node
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < dist[neighbor]:
                dist[neighbor] = distance
                prev[neighbor] = current_node
                q.append((neighbor, distance))
    
    # If we reached the end of the while loop, it means the target node is unreachable
    return (float("inf"), None)

