def shortest_path(graph, source, target):
    import heapq
    from collections import defaultdict

    # If target is not provided, treat it as infinity and use a simple BFS for unweighted graphs
    if target is None:
        target = float("inf")

    # Initialize the priority queue with source node
    queue = [(0, source, [source])]
    visited = set()

    while queue:
        (cost, current, path) = heapq.heappop(queue)

        if current == target:
            return (cost, path)

        if current not in visited:
            visited.add(current)
            for neighbor, weight in graph.get(current, []):
                if neighbor not in visited:
                    if target == float("inf"):
                        heapq.heappush(queue, (cost + weight, neighbor, path + [neighbor]))
                    else:
                        if cost + weight <= target:
                            heapq.heappush(queue, (cost + weight, neighbor, path + [neighbor]))

    # If target is unreachable, return (float("inf"), None)
    return (float("inf"), None)

