def shortest_path(graph, source, target):
    # Initialize distances and paths
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    paths = {source: [source]}

    # Priority queue to deal with shortest distances
    from heapq import heappush, heappop
    priority_queue = [(0, source)]

    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        # If we reached the target, return the path
        if current_node == target:
            return (current_distance, paths[current_node])

        # Skip if we've already found a shorter path to this node
        if current_distance > distances[current_node]:
            continue

        for neighbour, weight in graph[current_node].items():
            distance = current_distance + weight

            # If we found a better path, update the distances and paths
            if distance < distances[neighbour]:
                distances[neighbour] = distance
                paths[neighbour] = paths[current_node] + [neighbour]
                heappush(priority_queue, (distance, neighbour))

    # If there is no path, return infinity and None
    return (float('inf'), None)

