```python
def shortest_path(graph, source, target):
    # Priority queue to store the nodes to be processed, sorted by distance to the source
    priority_queue = [(0, source)]  # (distance, node)
    # Dictionary to store the shortest path to each node
    distances = {node: float('inf') for node in graph}
    distances[source] = 0  # Distance to the source is 0
    # Dictionary to store the previous node on the shortest path
    previous_nodes = {}

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        # If we reached the target node, we can reconstruct the path
        if current_node == target:
            path = []
            while current_node in previous_nodes:
                path.append(current_node)
                current_node = previous_nodes[current_node]
            path.append(source)  # Add the source node at the end of the path
            path.reverse()  # Reverse the list to get the correct order
            return (current_distance, path)

        # If we already found a shorter path to the current node, skip it
        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # If we found a shorter path to the neighbor, update the distances and previous nodes
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heapq.heappush(priority_queue, (distance, neighbor))

    # If we reach here, it means the target is unreachable
    return (float('inf'), None)

